#include<bits/stdc++.h>

using namespace std;

int nearest(int x,set<int> &st){
  auto it=st.find(x);
  int res=2e9;
  if(it!=st.begin()){
    auto jt=it; jt--;
    res=min(res,x-(*jt));
  }
  it++;
  if(it!=st.end()){
    res=min(res,(*it)-x);
  }
  return res;
}

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n;
  cin >> n;
  int res=0;
  set<int> st;
  {
    int x;
    cin >> x;
    st.insert(0);
    st.insert(x);
    res+=2*x;
    cout << res << "\n";
  }
  for(int i=1;i<n;i++){
    int x;
    cin >> x;
    vector<int> hit;
    auto it=st.lower_bound(x);
    if(it!=st.end()){hit.push_back(*it);}
    if(it!=st.begin()){
      it--;
      hit.push_back(*it);
    }
    for(auto &nx : hit){
      res-=nearest(nx,st);
    }
    st.insert(x);
    hit.push_back(x);
    for(auto &nx : hit){
      res+=nearest(nx,st);
    }
    cout << res << "\n";
  }
  return 0;
}

#include<bits/stdc++.h>

using namespace std;

int main(){
  ios::sync_with_stdio(false);
  cin.tie(nullptr);

  int n;
  cin >> n;
  int res=0;
  set<int> st;
  map<int,int> mp;
  {
    int x;
    cin >> x;
    st.insert(0);
    st.insert(x);
    mp[0]=x;
    mp[x]=x;
    res+=2*x;
    cout << res << "\n";
  }
  for(int i=1;i<n;i++){
    int x;
    cin >> x;
    vector<int> hit;
    auto it=st.lower_bound(x);
    if(it!=st.end()){hit.push_back(*it);}
    if(it!=st.begin()){
      it--;
      hit.push_back(*it);
    }
    st.insert(x);
    mp[x]=2e9;
    for(auto &nx : hit){
      res-=mp[nx];
      mp[nx]=min(mp[nx],abs(nx-x));
      res+=mp[nx];
      mp[x]=min(mp[x],abs(nx-x));
    }
    res+=mp[x];
    cout << res << "\n";
  }
  return 0;
}
